import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Eye, EyeOff, User, Mail, Lock, Fingerprint, Shield, Zap, ChevronRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { useAuth } from "@/contexts/AuthContext";

const BG_IMAGE = "data:image/jpeg;base64,";

const Auth = () => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();
  const { login } = useAuth();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isSignUp && !fullName.trim()) { toast.error("Please enter your full name"); return; }
    if (!email.trim()) { toast.error("Please enter your email"); return; }
    if (!password.trim() || password.length < 6) { toast.error("Password must be at least 6 characters"); return; }

    if (isSignUp) {
      toast.success("Account created! Use the test credentials to sign in.");
      setIsSignUp(false);
      return;
    }

    const success = login(email, password);
    if (success) {
      toast.success("Signed in successfully!");
      navigate("/dashboard");
    } else {
      toast.error("Invalid credentials. Use admin@trackvault.com / admin123");
    }
  };

  return (
    <div className="h-screen flex bg-[hsl(222,47%,7%)] overflow-hidden">
      {/* Left Panel — Background image */}
      <div className="hidden lg:flex lg:w-[55%] relative overflow-hidden flex-col justify-between p-10">
        {/* Background image */}
        <div
          className="absolute inset-0 bg-cover bg-center bg-no-repeat"
          style={{ backgroundImage: `url(${BG_IMAGE})` }}
        />
        {/* Dark overlay */}
        <div className="absolute inset-0 bg-gradient-to-br from-[hsl(222,47%,5%,0.65)] via-[hsl(200,60%,8%,0.5)] to-[hsl(230,35%,5%,0.7)]" />

        {/* Top branding */}
        <div className="relative z-10">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[hsl(213,80%,57%)] to-[hsl(258,80%,50%)] flex items-center justify-center shadow-[0_0_20px_hsl(213,80%,57%,0.4)]">
              <Zap className="w-5 h-5 text-white" />
            </div>
            <span className="text-xl font-bold tracking-wider text-white drop-shadow-lg">TRACKVAULT</span>
          </div>
          <p className="text-xs tracking-[0.3em] uppercase text-[hsl(213,80%,80%,0.7)] font-medium">Asset Intelligence Platform</p>
        </div>

       {/* Description */}
{/* Description */}
<div className="relative z-10 max-w-md mt-2">
  <p className="text-[hsl(213,30%,90%)] text-base sm:text-base leading-relaxed drop-shadow-sm text-left">
    Real-time equipment tracking, smart maintenance scheduling, and intelligent asset management — all in one platform.
  </p>
</div>

{/* Stats */}
<div className="relative z-10 flex gap-6 ">
  {[
    { value: "1.2K+", label: "ASSETS TRACKED" },
    { value: "99.9%", label: "UPTIME" },
    { value: "50+", label: "DEPARTMENTS" },
  ].map((stat) => (
    <div key={stat.label} className="flex flex-col items-start">
      {/* Value — slightly up */}
      <p className="text-3xl sm:text-3xl font-bold -mb-1 text-transparent bg-clip-text bg-gradient-to-r from-[hsl(213,80%,65%)] to-[hsl(258,80%,60%)]">
        {stat.value}
      </p>

      {/* Label — tight to value */}
      <p className="text-[10px] sm:text-xs tracking-[0.15em] text-[hsl(213,40%,75%,0.7)] font-medium">
        {stat.label}
      </p>
    </div>
  ))}
</div>
      </div>

     {/* Right Panel — Auth Form */}
{/* Right Panel — Auth Form */}
<div className="w-full lg:w-[45%] relative flex items-center justify-center p-6 sm:p-10 overflow-y-auto">

  {/* Gradient Background */}
  <div
    className="absolute inset-0"
    style={{
      background: `
        radial-gradient(ellipse 80% 45% at 30% 10%, hsla(215, 100%, 58%, 0.22) 0%, transparent 100%),
        radial-gradient(ellipse 75% 50% at 75% 88%, hsla(270, 80%, 56%, 0.28) 0%, transparent 100%),
        radial-gradient(ellipse 90% 90% at 50% 50%, transparent 50%, hsla(245, 60%, 3%, 0.5) 100%)
      `,
      pointerEvents: "none",
      zIndex: 0,
    }}
  />

  {/* Content */}
  <div className="relative z-10 w-full max-w-md">

    {/* Header */}
    <div className="text-center mb-8">
      <div className="lg:hidden flex items-center justify-center gap-2 mb-6">
        <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-[hsl(215,90%,60%)] to-[hsl(270,80%,60%)] flex items-center justify-center">
          <Zap className="w-4 h-4 text-white" />
        </div>
        <span className="text-lg font-bold tracking-wider text-white">TRACKVAULT</span>
      </div>
      <h1 className="text-2xl font-bold text-white mb-1">Get started</h1>
      <p className="text-sm text-[hsl(215,20%,50%)]">
        {isSignUp ? "Create your account to get started" : "Welcome back, sign in to continue"}
      </p>
    </div>

    {/* Test credentials */}
    {!isSignUp && (
      <div className="mb-6 p-3 rounded-xl border border-[hsl(215,90%,60%,0.2)] bg-[hsl(215,90%,60%,0.06)]">
        <p className="text-xs text-[hsl(215,90%,70%)] font-medium">
          Test credentials: admin@trackvault.com / admin123
        </p>
      </div>
    )}

    {/* Tabs */}
    <div className="flex rounded-xl bg-[hsl(223,37%,13%)] p-1 mb-8 border border-[hsl(222,20%,20%)]">
      <button
        onClick={() => setIsSignUp(false)}
        className={`flex-1 py-2.5 text-sm font-medium rounded-lg transition-all duration-300 ${
          !isSignUp
            ? "bg-gradient-to-r from-[hsl(215,90%,60%)] to-[hsl(270,80%,60%)] text-white shadow-lg shadow-[hsl(215,90%,60%,0.25)]"
            : "text-[hsl(215,20%,50%)] hover:text-[hsl(215,20%,65%)]"
        }`}
      >
        Sign In
      </button>

      <button
        onClick={() => setIsSignUp(true)}
        className={`flex-1 py-2.5 text-sm font-medium rounded-lg transition-all duration-300 ${
          isSignUp
            ? "bg-gradient-to-r from-[hsl(215,90%,60%)] to-[hsl(270,80%,60%)] text-white shadow-lg shadow-[hsl(215,90%,60%,0.25)]"
            : "text-[hsl(215,20%,50%)] hover:text-[hsl(215,20%,65%)]"
        }`}
      >
        Sign Up
      </button>
    </div>

    {/* Form */}
    <form onSubmit={handleSubmit} className="space-y-5">

      {isSignUp && (
        <div className="space-y-2">
          <Label className="text-xs font-semibold uppercase text-[hsl(215,20%,45%)]">
            Full Name
          </Label>
          <div className="relative">
            <User className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-[hsl(215,20%,40%)]" />
            <Input
              type="text"
              placeholder="John Doe"
              value={fullName}
              onChange={(e) => setFullName(e.target.value)}
              className="pl-11 h-12 bg-[hsl(223,37%,13%)] border-[hsl(222,20%,20%)] text-white rounded-xl"
            />
          </div>
        </div>
      )}

      {/* Email */}
      <div className="space-y-2">
        <Label className="text-xs font-semibold uppercase text-[hsl(215,20%,45%)]">
          Email
        </Label>
        <div className="relative">
          <Mail className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-[hsl(215,20%,40%)]" />
          <Input
            type="email"
            placeholder="you@company.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="pl-11 h-12 bg-[hsl(223,37%,13%)] border-[hsl(222,20%,20%)] text-white rounded-xl"
          />
        </div>
      </div>

      {/* Password */}
      <div className="space-y-2">
        <Label className="text-xs font-semibold uppercase text-[hsl(215,20%,45%)]">
          Password
        </Label>
        <div className="relative">
          <Lock className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-[hsl(215,20%,40%)]" />
          <Input
            type={showPassword ? "text" : "password"}
            placeholder="••••••••"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="pl-11 pr-11 h-12 bg-[hsl(223,37%,13%)] border-[hsl(222,20%,20%)] text-white rounded-xl"
          />
        </div>
      </div>

      {/* 🔥 Premium Button with Shine Effect */}
      <button
        type="submit"
        className="relative w-full h-12 rounded-xl overflow-hidden text-sm font-semibold text-white 
        bg-gradient-to-r from-[hsl(215,90%,60%)] to-[hsl(270,80%,60%)] 
        shadow-lg shadow-[hsl(215,90%,60%,0.25)] transition-all duration-300 group"
      >
        {/* Shine effect */}
        <span className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent 
        translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></span>

        <span className="relative z-10 flex items-center justify-center">
          {isSignUp ? "Create Account" : "Sign In"}
          <ChevronRight className="w-4 h-4 ml-1" />
        </span>
      </button>

    </form>

  </div>
</div>
    </div>
  );
};

export default Auth;